//
//  LocalizationManager.swift
//  SwiftMandarin
//
//  In-app language switching between the English and Mandarin (简体中文)
//  versions of the app, independent of the device's system language.
//
//  How it works
//  ------------
//  The UI is built almost entirely from SwiftUI string literals
//  (`Text("…")`, `Label("…")`, `.navigationTitle("…")`, …) which Xcode
//  extracts into `Localizable.xcstrings`. At runtime every one of those
//  resolves through `Bundle.main.localizedString(forKey:value:table:)`.
//
//  To switch language live — without forcing the user to change their device
//  language or relaunch — we swap `Bundle.main`'s class for a subclass that
//  redirects that one method to whichever `.lproj` the user picked. Combined
//  with re-keying the view tree (`.id(language)`) and updating the
//  `\.locale` environment, the whole app flips between English and Chinese
//  the moment the toggle changes. This is the standard, App-Store-safe
//  technique for an in-app language picker; it uses only public ObjC runtime
//  APIs and needs no entitlements.
//

import Foundation
import SwiftUI

// MARK: - App Language

/// The two UI languages the app ships. Raw values are the `.lproj` / locale
/// identifiers so they map directly onto bundle lookups and `Locale`.
enum AppLanguage: String, CaseIterable, Identifiable, Codable {
    case english = "en"
    case chinese = "zh-Hans"

    var id: String { rawValue }

    /// Name shown in its own language so each option is recognizable
    /// regardless of the currently active UI language.
    var displayName: String {
        switch self {
        case .english: return "English"
        case .chinese: return "中文"
        }
    }

    /// SF Symbol used next to the option in the language picker.
    /// (`character.book.closed.fill.zh` requires iOS 18+, so use a symbol
    /// available on every supported OS.)
    var iconName: String {
        switch self {
        case .english: return "a.circle"
        case .chinese: return "character.book.closed.fill"
        }
    }

    var locale: Locale { Locale(identifier: rawValue) }

    /// Nonisolated snapshot of the persisted UI language, for contexts that
    /// cannot hop to the main actor (e.g. App Intents entity display).
    /// Mirrors `LocalizationManager`'s persistence key and first-launch
    /// default (device language when Chinese, otherwise English).
    static var persisted: AppLanguage {
        if let raw = UserDefaults.standard.string(forKey: "app_language"),
           let language = AppLanguage(rawValue: raw) {
            return language
        }
        let preferred = Locale.preferredLanguages.first ?? "en"
        return preferred.lowercased().hasPrefix("zh") ? .chinese : .english
    }
}

// MARK: - Localization Manager

/// Observable, app-wide controller for the in-app UI language.
///
/// Changing `language` persists the choice, repoints `Bundle.main` at the
/// matching `.lproj`, and (because it is `@Observable`) drives a SwiftUI
/// refresh wherever the value is read — see `SwiftMandarinApp` which keys the
/// root view's identity to it.
@Observable
@MainActor
final class LocalizationManager {

    static let shared = LocalizationManager()

    private enum Keys {
        static let appLanguage = "app_language"
    }

    /// The active UI language. Setting it persists the choice and updates the
    /// active localization bundle so subsequent string lookups switch over.
    /// The interface language doubles as the user's NATIVE language, so the
    /// learner-mode preference is kept in sync: a 中文 interface means a native
    /// Mandarin speaker learning English, and vice versa.
    var language: AppLanguage {
        didSet {
            guard oldValue != language else { return }
            UserDefaults.standard.set(language.rawValue, forKey: Keys.appLanguage)
            Bundle.setLanguageOverride(language.rawValue)
            AppPreferences.shared.syncLearnerMode(toInterfaceLanguage: language)
        }
    }

    /// The interface language is treated as the user's native language.
    var nativeIsChinese: Bool { language == .chinese }

    /// The language the user is learning — always the opposite of the UI
    /// language (中文 UI → learning English; English UI → learning Mandarin).
    var learningIsChinese: Bool { language == .english }

    /// Locale to inject into the SwiftUI environment so number/date/plural
    /// formatting matches the chosen UI language.
    var locale: Locale { language.locale }

    private init() {
        let saved = UserDefaults.standard.string(forKey: Keys.appLanguage)
        let initial = saved.flatMap(AppLanguage.init(rawValue:)) ?? Self.systemDefault()
        self.language = initial
        // Apply immediately so the very first frame already renders in the
        // selected language (this runs at app construction, before any view).
        Bundle.setLanguageOverride(initial.rawValue)
    }

    /// First-launch default: follow the device language when it is Chinese,
    /// otherwise fall back to English.
    private static func systemDefault() -> AppLanguage {
        let preferred = Locale.preferredLanguages.first ?? "en"
        return preferred.lowercased().hasPrefix("zh") ? .chinese : .english
    }

    /// Flip between the two languages (used by a simple toggle control).
    func toggle() {
        language = (language == .english) ? .chinese : .english
    }

    /// Resolve a localization key against the currently selected language.
    /// Use this for user-facing strings that are *not* SwiftUI string-literal
    /// `Text`/`Label` (e.g. strings assembled in services or passed verbatim).
    /// Reading `language` here registers a SwiftUI dependency so call sites
    /// inside a view body re-evaluate when the language changes.
    func localized(_ key: String, table: String? = nil) -> String {
        _ = language
        return Bundle.main.localizedString(forKey: key, value: key, table: table)
    }
}

/// Convenience free function for the common case.
/// `Text(L("Some key"))` shows the translated string and reacts to language
/// changes when used inside a view body.
@MainActor
func L(_ key: String) -> String {
    LocalizationManager.shared.localized(key)
}

// MARK: - Localized presentation surfaces

extension View {
    /// Re-applies the in-app UI language to a presented surface (a `.sheet`,
    /// `.fullScreenCover`, or `.popover`). Such surfaces are hosted in a fresh
    /// context that does NOT reliably inherit the root window's `\.locale`
    /// environment, so without this their text stays in the device language
    /// instead of the user's chosen app language. Apply it to the root view
    /// inside every presentation closure.
    func localizedSurface() -> some View {
        modifier(LocalizedSurfaceModifier())
    }
}

private struct LocalizedSurfaceModifier: ViewModifier {
    @State private var localization = LocalizationManager.shared
    func body(content: Content) -> some View {
        content
            .environment(\.locale, localization.locale)
            .id(localization.language)
    }
}

// MARK: - Runtime bundle override

private var bundleLanguageAssociationKey: UInt8 = 0

extension Bundle {

    /// Swap `Bundle.main`'s class exactly once so its localized-string lookups
    /// can be redirected at runtime. Idempotent and thread-safe.
    private static let installLanguageOverrideOnce: Void = {
        object_setClass(Bundle.main, LanguageOverrideBundle.self)
    }()

    /// Point `Bundle.main` at the `.lproj` for `code` (e.g. `"zh-Hans"`).
    /// If that `.lproj` is missing (e.g. the source language has no compiled
    /// `.lproj`), the override is cleared and lookups fall back to the normal
    /// bundle, which already serves the development-language strings.
    static func setLanguageOverride(_ code: String?) {
        _ = installLanguageOverrideOnce
        let override: Bundle?
        if let code,
           let path = Bundle.main.path(forResource: code, ofType: "lproj"),
           let languageBundle = Bundle(path: path) {
            override = languageBundle
        } else {
            override = nil
        }
        objc_setAssociatedObject(
            Bundle.main,
            &bundleLanguageAssociationKey,
            override,
            .OBJC_ASSOCIATION_RETAIN_NONATOMIC
        )
    }

    /// The currently installed override bundle, if any.
    fileprivate var languageOverrideBundle: Bundle? {
        objc_getAssociatedObject(self, &bundleLanguageAssociationKey) as? Bundle
    }
}

/// `Bundle.main` is reclassed to this so all localized-string lookups —
/// including the ones SwiftUI performs for `Text("…")` — can be routed to the
/// user-selected language bundle. Adds no stored properties (required for
/// `object_setClass` to be safe).
private final class LanguageOverrideBundle: Bundle, @unchecked Sendable {
    override func localizedString(forKey key: String, value: String?, table tableName: String?) -> String {
        if let override = languageOverrideBundle {
            return override.localizedString(forKey: key, value: value, table: tableName)
        }
        return super.localizedString(forKey: key, value: value, table: tableName)
    }
}

//
//  WordTranslationService.swift
//  SwiftMandarin
//
//  Service for translating individual words/phrases using Apple's Translation
//  API (iOS 18+/macOS 15+). On older systems it falls back to the configured
//  AI provider, so word lookups keep working on iOS 17.
//

import Foundation
import Translation

/// Service for translating individual words using Apple's Translation API
@Observable
final class WordTranslationService {

    static let shared = WordTranslationService()

    /// Cache for translated words to avoid repeated API calls
    private var translationCache: [String: String] = [:]

    private init() {}

    // MARK: - Public Methods

    /// Translate a single word or phrase from Chinese to English
    /// Uses installed language packs (requires languages to be pre-downloaded)
    /// - Parameter word: The Chinese word/phrase to translate
    /// - Returns: The English translation
    func translateToEnglish(_ word: String) async throws -> String {
        // Check cache first
        let cacheKey = "zh-en:\(word)"
        if let cached = translationCache[cacheKey] {
            return cached
        }

        let translation = try await systemOrAITranslate(word, sourceIsChinese: true)
        translationCache[cacheKey] = translation
        return translation
    }

    /// Translate a single word or phrase from English to Chinese
    /// Uses installed language packs (requires languages to be pre-downloaded)
    /// - Parameter word: The English word/phrase to translate
    /// - Returns: The Chinese translation
    func translateToChinese(_ word: String) async throws -> String {
        // Check cache first
        let cacheKey = "en-zh:\(word)"
        if let cached = translationCache[cacheKey] {
            return cached
        }

        let translation = try await systemOrAITranslate(word, sourceIsChinese: false)
        translationCache[cacheKey] = translation
        return translation
    }

    /// Translate a word with automatic language detection
    /// - Parameters:
    ///   - word: The word to translate
    ///   - sourceIsChinese: Whether the source word is Chinese
    /// - Returns: The translated word in the opposite language
    func translate(_ word: String, sourceIsChinese: Bool) async throws -> String {
        if sourceIsChinese {
            return try await translateToEnglish(word)
        } else {
            return try await translateToChinese(word)
        }
    }

    /// Batch translate multiple words (more efficient for multiple lookups)
    /// - Parameters:
    ///   - words: Array of words to translate
    ///   - sourceIsChinese: Whether source words are Chinese
    /// - Returns: Dictionary mapping original words to translations
    func translateBatch(_ words: [String], sourceIsChinese: Bool) async throws -> [String: String] {
        var results: [String: String] = [:]
        var wordsToTranslate: [String] = []

        // Check cache first
        let cachePrefix = sourceIsChinese ? "zh-en:" : "en-zh:"
        for word in words {
            let cacheKey = "\(cachePrefix)\(word)"
            if let cached = translationCache[cacheKey] {
                results[word] = cached
            } else {
                wordsToTranslate.append(word)
            }
        }

        // Return early if all words were cached
        if wordsToTranslate.isEmpty {
            return results
        }

        if #available(iOS 26.0, macOS 26.0, *) {
            // Create translation session using installed languages
            let session = TranslationSession(
                installedSource: sourceIsChinese ? Locale.Language(identifier: "zh-Hans") : Locale.Language(identifier: "en"),
                target: sourceIsChinese ? Locale.Language(identifier: "en") : Locale.Language(identifier: "zh-Hans")
            )

            // Create batch requests with client identifiers for matching
            var requests: [TranslationSession.Request] = []
            for (index, word) in wordsToTranslate.enumerated() {
                requests.append(TranslationSession.Request(
                    sourceText: word,
                    clientIdentifier: "\(index)"
                ))
            }

            // Perform batch translation
            let responses = try await session.translations(from: requests)

            // Process responses and update cache
            for response in responses {
                if let clientId = response.clientIdentifier,
                   let index = Int(clientId),
                   index < wordsToTranslate.count {
                    let originalWord = wordsToTranslate[index]
                    let translation = response.targetText

                    results[originalWord] = translation
                    translationCache["\(cachePrefix)\(originalWord)"] = translation
                }
            }
        } else {
            // Pre-iOS 26: translate sequentially through the configured AI
            // provider (each result is cached, so repeat lookups are free).
            for word in wordsToTranslate {
                let translation = try await AIWordExplanationService.shared
                    .translateWithProvider(word, sourceIsChinese: sourceIsChinese)
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                guard !translation.isEmpty else { continue }
                results[word] = translation
                translationCache["\(cachePrefix)\(word)"] = translation
            }
        }

        return results
    }

    /// Clear the translation cache
    func clearCache() {
        translationCache.removeAll()
    }

    /// Get cached translation if available
    func getCachedTranslation(for word: String, sourceIsChinese: Bool) -> String? {
        let cacheKey = sourceIsChinese ? "zh-en:\(word)" : "en-zh:\(word)"
        return translationCache[cacheKey]
    }

    // MARK: - Backend Selection

    /// Apple's on-device Translation API where available (iOS 26+/macOS 26+;
    /// the standalone session initializer is newer than the SwiftUI task API),
    /// otherwise the user's configured AI provider.
    private func systemOrAITranslate(_ text: String, sourceIsChinese: Bool) async throws -> String {
        if #available(iOS 26.0, macOS 26.0, *) {
            let session = TranslationSession(
                installedSource: Locale.Language(identifier: sourceIsChinese ? "zh-Hans" : "en"),
                target: Locale.Language(identifier: sourceIsChinese ? "en" : "zh-Hans")
            )
            let response = try await session.translate(text)
            return response.targetText
        } else {
            return try await AIWordExplanationService.shared
                .translateWithProvider(text, sourceIsChinese: sourceIsChinese)
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
    }
}

