                            .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(isSaved || chineseTranslation.isEmpty)
                }
                .padding()
            }
            .navigationTitle("单词详情")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("完成") {
                        dismiss()
                    }
                }
            }
            .task {
                // Auto-translate when sheet appears if no translation available
                if chineseTranslation.isEmpty {
                    await translateWord()
                }
            }
        }
    }

    private func translateWord() async {
        isLoading = true
        defer { isLoading = false }

        do {
            // Translate English word to Chinese
            let translation = try await WordTranslationService.shared.translateToChinese(word.lemma)
            fullTranslation = translation
        } catch {
            // Handle error silently for now
            fullTranslation = word.translation ?? ""
        }
    }

    private func saveToVocabulary() {
        // Save with Chinese translation as the main term, English word as definition
        let term = SavedTerm(
            chinese: chineseTranslation,
            pinyin: PinyinConverter.convert(chineseTranslation),
            definition: word.lemma.caseInsensitiveCompare(word.text) == .orderedSame ? word.text : "\(word.text) (\(word.lemma))",
            partOfSpeech: word.partOfSpeech.rawValue
        )
        savedTermsStore.add(term)
    }
}

